function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (str.length === 0) {
    return str;
  }

  // Strategy:
  // 1. Insert '_' between (lowercase/digit) and uppercase.
  // 2. Insert '_' between (uppercase followed by lowercase) and the previous uppercase (to break acronyms).
  // 3. Convert entire string to lowercase.

  // First pass: Insert underscores between (lowercase/digit) + (uppercase)
  // This handles "parseHTTP" -> "parse_HTTP", "getV2" -> "get_V2"
  let result = str.replace(/([a-z0-9])([A-Z])/g, '$1_$2');

  // Second pass: Insert underscores between (uppercase) + (uppercase) + (lowercase)
  // This handles "HTTPResponse" -> "HTTP_Response" (insert before the last uppercase of the sequence)
  // Specifically: "HTTP" + "R" (where R is followed by lowercase) -> "HTTP_R"
  // Regex explanation: ([A-Z])([A-Z])([a-z]) -> $1_$2$3
  // This ensures we don't break "XML" (no lowercase after) but do break "XMLHttpRequest" -> "XML_http"
  result = result.replace(/([A-Z])([A-Z])([a-z])/g, '$1_$2$3');

  return result.toLowerCase();
}

module.exports = { camelToSnake };
