    throw new TypeError('qs must be a string');
  }

  // Remove leading '?' if present
  if (qs.startsWith('?')) {
    qs = qs.slice(1);
  }

  const result = {};

  // Split by '&', but skip empty parts (handles trailing && or empty qs)
  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (pair === '') {
      continue;
    }

    let key, value;
    const eqIndex = pair.indexOf('=');

    if (eqIndex === -1) {
      // No '=' found: key is whole string, value is empty string
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode key and value: + -> space, then percent-encode decoding
    const decodeFn = (str) => {
      // Replace + with space
      const withSpaces = str.replace(/\+/g, ' ');
      // Decode percent-escapes
      try {
        return decodeURIComponent(withSpaces);
      } catch (e) {
        if (e instanceof URIError) throw e;
        throw new URIError('Malformed percent-encoding');
      }
    };

    const decodedKey = decodeFn(key);
    const decodedValue = decodeFn(value);

    // Skip if key is empty after decoding
    if (decodedKey === '') {
      continue;
    }

    // If key already exists, convert to array or append
    if (Object.prototype.hasOwnProperty.call(result, decodedKey)) {
      const existing = result[decodedKey];
      if (Array.isArray(existing)) {
        existing.push(decodedValue);
      } else {
        result[decodedKey] = [existing, decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

