function isValidCardNumber(input) {
  if (typeof input !== 'string') {
    return false;
  }

  const digits = [];
  let index = 0;

  while (index < input.length) {
    const char = input[index];

    if (char === ' ' || char === '-') {
      index++;
      continue;
    }

    if (char >= '0' && char <= '9') {
      digits.push(parseInt(char, 10));
    } else {
      return false;
    }

    index++;
  }

  if (digits.length < 12 || digits.length > 19) {
    return false;
  }

  let sum = 0;
  let doubleIt = false;

  for (let i = digits.length - 1; i >= 0; i--) {
    let digit = digits[i];

    if (doubleIt) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    doubleIt = !doubleIt;
  }

  return sum % 10 === 0;
}

