function topoSort(graph) {
  // Create a copy of the graph to avoid modifying input and to handle implicit tasks
  const graphCopy = {};
  const allTasks = new Set();

  // Collect all tasks: keys and all dependency names
  for (const task of Object.keys(graph)) {
    graphCopy[task] = [...new Set(graph[task])]; // Deduplicate dependencies
    for (const dep of graphCopy[task]) {
      allTasks.add(dep);
      if (!graphCopy[dep]) {
        graphCopy[dep] = []; // Ensure implicit tasks have an entry
      }
    }
    allTasks.add(task);
  }

  // Ensure all tasks have an entry even if they are only dependencies
  for (const task of allTasks) {
    if (!graphCopy[task]) {
      graphCopy[task] = [];
    }
  }

  // Calculate in-degree (number of dependencies) for each task
  const inDegree = {};
  for (const task of allTasks) {
    inDegree[task] = graphCopy[task].length;
  }

  const result = [];
  const cycleSize = allTasks.size;

  while (result.length < cycleSize) {
    // Find all tasks with in-degree 0
    const candidates = Object.keys(inDegree)
      .filter(task => inDegree[task] === 0)
      .sort(); // Sort alphabetically to pick the smallest string

    if (candidates.length === 0) {
      throw new Error("Cycle detected");
    }

    // Pick the smallest task
    const nextTask = candidates[0];

    // Add to result
    result.push(nextTask);

    // Remove from consideration and update dependencies
    // Decrement in-degree for tasks that depend on this one
    for (const dependent of allTasks) {
      if (graphCopy[dependent].includes(nextTask)) {
        inDegree[dependent]--;
      }
    }

    // Mark as processed by setting in-degree to -1 so it doesn't get picked again
    inDegree[nextTask] = -1;
  }

  return result;
}

