from datetime import date, datetime
from typing import Iterable

def business_days(start: str, end: str, holidays: Iterable[str] = ()) -> int:
    """Count business days in [start, end) range, excluding weekends and holidays."""

    def parse_date(s: str) -> date:
        try:
            return datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError as e:
            raise ValueError(f"Invalid date string: {s!r}") from e

    start_date = parse_date(start)
    end_date = parse_date(end)

    if end_date < start_date:
        raise ValueError("end must not be earlier than start")

    # Validate and normalize holidays
    holiday_set = set()
    for h in holidays:
        try:
            holiday_set.add(parse_date(h))
        except ValueError as e:
            raise ValueError(f"Invalid date string in holidays: {h!r}") from e

    count = 0
    current = start_date
    end_date_excl = end_date  # half-open: stop before this date

    while current < end_date_excl:
        # Skip weekends (0=Monday, 6=Sunday)
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current += 1  # move to next day

    return count
