    // Skip empty parts (handles trailing &, empty pairs like '&&')
    if (part.length === 0) {
      continue;
    }

    // Split at the first '=' only
    let keyEnd = part.indexOf('=');
    let key, value;

    if (keyEnd === -1) {
      // No '=' found, entire part is key
      key = part;
      value = '';
    } else {
      key = part.slice(0, keyEnd);
      value = part.slice(keyEnd + 1);
