from datetime import date, timedelta
from typing import Iterable, Set


def business_days(start: str, end: str, holidays: Iterable[str] = ()) -> int:
    """Count working days in a half-open range [start, end) excluding holidays."""
    # Parse start and end dates
    try:
        start_date = date.fromisoformat(start)
        end_date = date.fromisoformat(start) if start == end else date.fromisoformat(end)
    except ValueError as e:
        raise ValueError("Invalid date string") from e

    # Validate date order
    if end_date < start_date:
        raise ValueError("end must not be earlier than start")

    # Parse holidays into a set for O(1) lookup
    holiday_set: Set[date] = set()
    for h in holidays:
        try:
            holiday_set.add(date.fromisoformat(h))
        except ValueError:
            raise ValueError(f"Invalid holiday date: {h}") from None

    count = 0
    current = start_date
    end_date = date.fromisoformat(end)  # Ensure we have a proper date object

    if current >= end_date:
        return 0

    # Iterate through each day in [start, end)
    while current < end_date:
        # Check if weekday (Monday=0 to Friday=4)
        if current.weekday() < 5:
            if current not in holiday_set:
                count += 1
        current += timedelta(days=1)

    return count
