        # Wait, we can't import OrderedDict without importing from collections.
        # collections is standard library, so it's allowed.
        # Let's use OrderedDict for O(1) operations.
        from collections import OrderedDict
        self._cache = OrderedDict()  # key -> value, ordered from LRU to MRU

    def get(self, key, default=None):
        if key not in self._cache:
            return default
        self._cache.move_to_end(key)  # Move to end (most recently used)
        return self._cache[key]

    def put(self, key, value):
        if key in self._cache:
            self._cache[key] = value
            self._cache.move_to_end(key)
        else:
            if len(self._cache) >= self.capacity:
                self._cache.popitem(last=False)  # Remove LRU (first item)
