        elif isinstance(value, list):
            result = {}
            for i, item in enumerate(value):
                item_key = f"{prefix}{sep}{i}" if prefix else str(i)
                result.update(_walk(item, item_key))
            return result
        else:
            return {prefix: value} if prefix else {"": value}

