    return false;
  }

  // Check all characters are digits
  if (!/^\d+$/.test(cleaned)) {
    return false;
  }

  let sum = 0;
  let doubleDigit = false;

  // Process from right to left
  for (let i = cleaned.length - 1; i >= 0; i--) {
    let digit = parseInt(cleaned[i], 10);

    if (doubleDigit) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    doubleDigit = !doubleDigit;
  }

  return sum % 10 === 0;
}

