    throw new TypeError('Argument must be a string');
  }

  if (str.length === 0) {
    return str;
  }

  // First pass: insert underscores
  // 1. Between a lower-case letter or digit and a following upper-case letter
  // 2. Between an upper-case letter and a following upper-case letter that is followed by a lower-case letter (end of acronym)
  let result = '';
  for (let i = 0; i < str.length; i++) {
    const current = str[i];
    const next = i < str.length - 1 ? str[i + 1] : null;
    const prev = i > 0 ? str[i - 1] : null;

    let insert = false;

    if (prev) {
      // Rule 1: prev is lower-case or digit, next is upper-case
      const prevIsLowerOrDigit = /[a-z0-9]/.test(prev);
      const nextIsUpper = /[A-Z]/.test(next);
      if (prevIsLowerOrDigit && nextIsUpper) {
        insert = true;
      } else {
        // Rule 2: prev is Upper, next is Upper, and next is followed by Lower (meaning prev is end of acronym)
        // Wait: We are at `prev` (which is i-1) and `current` (which is i).
        // We need to check if `prev` is Upper, `current` is Upper, and `next` (i+1) is Lower.
        if (prevIsLowerOrDigit === false && /[A-Z]/.test(prev) && nextIsUpper) {
          const nextIsLower = /[a-z]/.test(next);
          if (nextIsLower) {
            insert = true;
          }
        }
      }
    }

    if (insert) {
