  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (ch === ' ' || ch === '-') {
      continue;
    }
    if (ch >= '0' && ch <= '9') {
      digits.push(parseInt(ch, 10));
    } else {
      return false;
    }
  }

  if (digits.length < 12 || digits.length > 19) {
    return false;
  }

  let sum = 0;
  let doubleIt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let digit = digits[i];
    if (doubleIt) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }
    sum += digit;
    doubleIt = !doubleIt;
  }

  return sum % 10 === 0;
}

