function render(template, data) {
  if (typeof template !== 'string') {
    throw new TypeError('template must be a string');
  }

  // Regex to match {{, optional whitespace, path, optional whitespace, }}
  // Path segments are characters other than {, }, ., whitespace.
  // The path itself must contain at least one valid segment.
  // Segments: [^{}. \t\r\n]+
  const PLACEHOLDER_REGEX = /\{\{(\s*)([^{}.\s]+(?:\.[^{}.\s]+)*)(\s*)\}\}/g;

  return template.replace(PLACEHOLDER_REGEX, (match, whitespaceStart, path, whitespaceEnd) => {
    const segments = path.split('.');
    let current = data;

    for (let i = 0; i < segments.length; i++) {
      const segment = segments[i];

      // Check if current object has own property for segment
      if (!(segment in current) || !Object.prototype.hasOwnProperty.call(current, segment)) {
        return match; // Return original if missing at any step
      }

      current = current[segment];
    }

    // If final value is null or undefined, return empty string
    if (current == null) {
      return '';
    }

    return String(current);
  });
}

