        if key in self._order_map:
            idx = self._order_map[key]
            if idx != len(self._order) - 1:
                # Remove from current position and append to end
                self._order.pop(idx)
                self._order.append(key)
                self._order_map[key] = len(self._order) - 1
                # Shift indices for keys after the removed one
                for k_idx in range(self._order_map[key] + 1, len(self._order)):
                    self._order_map[self._order[k_idx]] = k_idx
        else:
            # This shouldn't happen in normal flow, but handle safely
            self._order.append(key)
            self._order_map[key] = len(self._order) - 1

    def _evict_if_needed(self):
        if len(self._cache) >= self.capacity:
            oldest_key = self._order[0]
            del self._cache[oldest_key]
            del self._order_map[oldest_key]
            self._order = self._order[1:]

