    throw new TypeError('qs must be a string');
  }

  // Remove optional leading '?'
  qs = qs.replace(/^\?/, '');

  // Split by '&' and filter empty pairs
  const pairs = qs.split('&');
  const result = Object.create(null);

  for (const pair of pairs) {
    if (pair === '') {
      continue;
    }

    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // Decode key and value: first replace '+' with ' ', then decode percent- escapes
    const decodeComponent = (str) => {
      try {
        // Replace '+' with space first
        const withSpace = str.replace(/\+/g, ' ');
        // Decode percent escapes as UTF-8
        return decodeURIComponent(withSpace);
      } catch (e) {
        if (e instanceof URIError) {
          throw e;
        }
        throw new URIError('Malformed percent-encoding');
      }
    };

    key = decodeComponent(key);
    value = decodeComponent(value);

    // Skip if decoded key is empty
    if (key === '') {
      continue;
    }

    // If key already exists, convert to array or append to array
    if (Object.prototype.hasOwnProperty.call(result, key)) {
      const existing = result[key];
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        result[key] = [existing, value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}

