function topoSort(graph) {
  // Create a copy of keys to avoid modifying input
  const taskSet = new Set();
  const dependencies = new Map();

  // Collect all tasks (both keys and values) and build dependency map
  for (const [task, deps] of Object.entries(graph)) {
    taskSet.add(task);
    // Add unique dependencies
    for (const dep of deps) {
      taskSet.add(dep);
    }
    // Store dependencies for this task (as a Set to ensure uniqueness and fast lookup)
    dependencies.set(task, new Set(deps));
  }

  // Track which tasks are still available (not yet placed)
  const remaining = new Set(taskSet);

  // Track which tasks have their dependencies satisfied
  // A task is "satisfied" when all its dependencies are either placed or not present in remaining
  const satisfied = new Set();

  const result = [];

  while (remaining.size > 0) {
    // Find all tasks where all dependencies are NOT in remaining (i.e., satisfied)
    let candidates = [];
    for (const task of remaining) {
      const deps = dependencies.get(task) || [];
      let allDepsSatisfied = true;
      for (const dep of deps) {
        if (remaining.has(dep)) {
          allDepsSatisfied = false;
          break;
        }
      }
      if (allDepsSatisfied) {
        candidates.push(task);
      }
    }

    if (candidates.length === 0) {
      throw new Error('cycle detected');
    }

    // Sort candidates by string order and pick the smallest
    candidates.sort();
    const nextTask = candidates[0];

    // Place the task
    result.push(nextTask);
    remaining.delete(nextTask);
  }

  return result;
}

