    start_date = _parse_date(start)
    end_date = _parse_date(end)

    if end_date < start_date:
        raise ValueError("end must be >= start")

    try:
        holiday_set = {_parse_date(h) for h in holidays}
    except ValueError as e:
        raise ValueError(f"Invalid ISO date string in holidays: {e}") from e

    current = start_date
    count = 0

