function isValidCardNumber(input) {
  if (typeof input !== 'string') {
    return false;
  }

  // Remove spaces and hyphens only
  const cleaned = input.replace(/[- ]/g, '');

  // Check length (12 to 19 digits)
  if (cleaned.length < 12 || cleaned.length > 19) {
    return false;
  }

  // Check for non-digit characters (any character that is not a digit)
  for (let i = 0; i < cleaned.length; i++) {
    const ch = cleaned.charCodeAt(i);
    if (ch < 48 || ch > 57) { // '0' to '9'
      return false;
    }
  }

  // Luhn algorithm
  let sum = 0;
  let shouldDouble = false;

  for (let i = cleaned.length - 1; i >= 0; i--) {
    let digit = cleaned.charCodeAt(i) - 48; // convert char to number

    if (shouldDouble) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    shouldDouble = !shouldDouble;
  }

  return sum % 10 === 0;
}

