function topoSort(graph) {
  // Build a set of all unique task names
  const allTasks = new Set();
  for (const task of Object.keys(graph)) {
    allTasks.add(task);
    for (const dep of graph[task]) {
      allTasks.add(dep);
    }
  }

  // Build dependency map: task -> set of dependencies (deduplicated)
  const deps = new Map();
  for (const task of allTasks) {
    deps.set(task, new Set());
  }
  for (const [task, dependencies] of Object.entries(graph)) {
    for (const dep of dependencies) {
      deps.set(task, new Set(deps.get(task)));
      deps.get(task).add(dep);
    }
  }

  const result = [];
  const completed = new Set();

  // Helper to check if a task is ready (all dependencies completed)
  const isReady = (task) => {
    const dependencies = deps.get(task);
    for (const dep of dependencies) {
      if (!completed.has(dep)) {
        return false;
      }
    }
    return true;
  };

  while (result.length < allTasks.size) {
    // Find all ready tasks
    const candidates = [];
    for (const task of allTasks) {
      if (!completed.has(task) && isReady(task)) {
        candidates.push(task);
      }
    }

    if (candidates.length === 0) {
      // No task is ready but we haven't completed all -> cycle
      throw new Error('cycle detected');
    }

    // Sort candidates lexicographically and pick the smallest
    candidates.sort();
    const next = candidates[0];
    result.push(next);
    completed.add(next);
  }

  return result;
}

