    for h in holidays:
        try:
            h_date = datetime.strptime(h, "%Y-%m-%d").date()
            holiday_set.add(h_date)
        except ValueError:
            raise ValueError(f"Invalid holiday date: {h}")

    count = 0
    current = start_date
    end_limit = end_date

    while current < end_limit:
