class LRUCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._store = {}  # Maps key -> node
        self._order = []  # List of keys ordered from LRU (index 0) to MRU (last)
        self._update_order = {}  # Maps key -> index in _order for O(1) lookup

    def _move_to_end(self, key):
        # Remove key from its current position and append to end
        idx = self._update_order[key]
        if idx != len(self._order) - 1:
            # Remove from middle and append
            self._order.pop(idx)
            # Update indices for all elements after the removed one
            for k in self._order[idx:]:
                self._update_order[k] = idx
                idx += 1
            self._order.append(key)
            self._update_order[key] = len(self._order) - 1
        else:
            # Already at end, but we still need to ensure the dict is consistent
            # (though in practice, if it's already at end, we don't need to move)
            pass

    def get(self, key, default=None):
        if key not in self._store:
            return default
        # Mark as most recently used
        self._move_to_end(key)
        return self._store[key]

    def put(self, key, value):
        if key in self._store:
            # Update value and move to end
            self._store[key] = value
            self._move_to_end(key)
        else:
            # Add new key
            self._store[key] = value
            self._order.append(key)
            self._update_order[key] = len(self._order) - 1
            # Check capacity
            if len(self._order) > self.capacity:
                # Remove least recently used (first element)
                lru_key = self._order[0]
                del self._store[lru_key]
                del self._update_order[lru_key]
                # Remove from order list and re-index remaining
                self._order.pop(0)
                # Rebuild indices for remaining elements efficiently
                for i, k in enumerate(self._order):
                    self._update_order[k] = i

    def __len__(self):
        return len(self._store)

    def __contains__(self, key):
        return key in self._store

    def keys(self):
        # Return keys from least recently used to most recently used
        return list(self._order)
