function topoSort(graph) {
  // Create a set of all task names (keys and values in dependencies)
  const allTasks = new Set();
  const deps = new Map(); // task -> Set of dependencies

  // Normalize input: ensure no mutation of input, and handle duplicates in lists
  for (const [task, depList] of Object.entries(graph)) {
    if (!Array.isArray(depList)) {
      throw new Error('Invalid graph: dependency list must be an array');
    }
    allTasks.add(task);
    const depSet = new Set(depList);
    deps.set(task, depSet);
  }

  // Add tasks that appear only in dependency lists
  for (const depList of deps.values()) {
    for (const dep of depList) {
      allTasks.add(dep);
    }
  }

  // Build a copy of dependencies for all tasks (including those without keys)
  const remainingDeps = new Map();
  for (const task of allTasks) {
    remainingDeps.set(task, new Set());
    if (deps.has(task)) {
      for (const dep of deps.get(task)) {
        remainingDeps.get(task).add(dep);
      }
    }
    // Ensure the task itself is not in its own dependency list if it was listed
    // (but the problem says "a task that depends on itself" is a cycle, so we keep it)
  }

  const result = [];
  const visited = new Set();

  // Helper to find next task
  function getNextTask() {
    let candidate = null;
    for (const task of allTasks) {
      if (visited.has(task)) continue;
      const deps = remainingDeps.get(task);
      if (deps.size === 0) {
        if (candidate === null || task < candidate) {
          candidate = task;
        }
      }
    }
    return candidate;
  }

  // Process tasks
  while (result.length < allTasks.size) {
    const task = getNextTask();
    if (task === null) {
      // Cycle detected
      // Find a task that still has dependencies to report cycle
      for (const t of allTasks) {
        if (!visited.has(t) && remainingDeps.get(t).size > 0) {
          return; // break and throw after loop
        }
      }
      throw new Error('cycle');
    }

    visited.add(task);
    result.push(task);

    // Remove this task from dependencies of others
    for (const otherTask of allTasks) {
      if (!visited.has(otherTask)) {
        remainingDeps.get(otherTask).delete(task);
      }
    }
  }

  return result;
}

