function topoSort(graph) {
  // Collect all tasks: keys and any names appearing only in dependency lists
  const taskSet = new Set();
  const dependencies = {}; // task -> Set of dependencies (deduplicated)

  // Build initial dependency map from keys
  for (const [task, deps] of Object.entries(graph)) {
    taskSet.add(task);
    const depSet = new Set();
    for (const dep of deps) {
      depSet.add(dep);
      taskSet.add(dep); // Ensure dependency names are tracked as tasks
      if (!dependencies[dep]) {
        dependencies[dep] = new Set();
      }
      // We will fill dependencies[task] later; here we just ensure structure
    }
    dependencies[task] = depSet;
  }

  // Ensure every task in taskSet has an entry in dependencies (even if empty)
  for (const task of taskSet) {
    if (!dependencies[task]) {
      dependencies[task] = new Set();
    }
  }

  // Ensure no modification to original graph or its internal arrays
  // We have already made copies via Set, so original graph is untouched.

  // To detect cycles and perform topological sort:
  // We'll track which tasks are placed and maintain in-degree based on remaining dependencies.
  // But since we need to pick smallest name among available, we'll maintain a Set of 'ready' tasks.

  // Build a dependency count for each task (how many of its deps are not yet placed)
  const pending = new Set(taskSet); // tasks not yet placed
  const remainingDeps = {}; // task -> Set of deps that are still not placed

  for (const task of taskSet) {
    remainingDeps[task] = new Set(dependencies[task]);
  }

  // Determine initial ready tasks (those with no remaining deps)
  const ready = new Set();
  for (const task of taskSet) {
    if (remainingDeps[task].size === 0) {
      ready.add(task);
    }
  }

  const result = [];

  while (ready.size > 0) {
    // Pick the smallest task by string order
    let smallest = null;
    for (const t of ready) {
      if (smallest === null || t < smallest) {
        smallest = t;
      }
    }

    if (smallest === null) break;

    result.push(smallest);
    pending.delete(smallest);
    ready.delete(smallest);

    // For each task that depends on 'smallest', reduce its pending deps
    // We need to know which tasks have 'smallest' as a dependency.
    // We can iterate over all tasks and check if 'smallest' is in their remainingDeps
    for (const task of pending) {
      if (remainingDeps[task].has(smallest)) {
        remainingDeps[task].delete(smallest);
        if (remainingDeps[task].size === 0) {
          ready.add(task);
        }
      }
    }
  }

  // Check for cycle: if there are still tasks not placed
  if (result.length < taskSet.size) {
    throw new Error("cycle detected");
  }

  return result;
}

module.exports = { topoSort };

