  }

  // If rounding made it 1024 and we have a larger unit, move up
  if (formatted === 1024 && unitIndex < 4) {
    formatted = 1;
    unitIndex++;
  }

  // Format the value: remove .0 if present
  let resultString;
  if (formatted % 1 === 0) {
