function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  // Split by commas, trimming whitespace, and filter out empty parts caused by trailing commas
  const parts = spec.split(',').map(s => s.trim()).filter(s => s.length > 0);

  const result = new Set(); // Using Set to handle duplicates automatically

  for (const part of parts) {
    // Check for invalid characters or format
    // Allowed: digits, one dash, optional leading zeros
    // Disallowed: letters, multiple dashes, plus sign, decimal point, empty parts (handled by filter), negative numbers (if we parse correctly)

    let partsArr;
    if (part.includes('-')) {
      // Must have exactly one dash and be two numbers
      if (part.split('-').length !== 2) {
        throw new SyntaxError(`Invalid part: "${part}"`);
      }

      const [loStr, hiStr] = part.split('-');

      // Check for empty lo or hi (e.g. "-5" or "5-")
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError(`Invalid part: "${part}"`);
      }

      // Check for signs or non-digits (except leading zeros are fine)
      // We allow leading zeros, but no +, no -, no decimals.
      // parseInt will handle leading zeros, but we need to ensure no other weird chars.
      if (/[^0-9]/.test(loStr) || /[^0-9]/.test(hiStr)) {
        throw new SyntaxError(`Invalid part: "${part}"`);
