      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError(`Range start greater than end in "${part}"`);
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      // Single number
      if (part === '') {
        // Should be caught by filter, but safety check
        throw new SyntaxError(`Invalid part: ""`);
      }
      // Check for non-digits (e.g. "7a", "1-2-3" handled above, "1.5" handled)
      if (/[^0-9]/.test(part)) {
        throw new SyntaxError(`Invalid part: "${part}"`);
      }

      const num = parseInt(part, 10);
      if (isNaN(num)) {
        throw new SyntaxError(`Invalid part: "${part}"`);
      }
      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
