function flatten(arr, depth = 1) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`Expected an array, got ${typeof arr}`);
  }

  if (depth === 0) {
    return arr.slice();
  }

  if (typeof depth !== 'number' || Number.isNaN(depth) || depth < 0) {
    throw new RangeError('depth must be a non-negative number or Infinity');
  }

  const result = [];
  const queue = [[arr, depth]];

  while (queue.length > 0) {
    const [currentArr, currentDepth] = queue.shift();

    if (currentDepth === 0) {
      result.push(...currentArr);
      continue;
    }

    for (const item of currentArr) {
      if (Array.isArray(item)) {
        queue.push([item, currentDepth - 1]);
      } else {
        result.push(item);
      }
    }
  }

  return result;
}

module.exports = { flatten };
