class Emitter {
  constructor() {
    this._listeners = {}; // { eventName: [{ once: boolean, fn }] }
  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    if (!this._listeners[event]) {
      this._listeners[event] = [];
    }
    this._listeners[event].push({ once: false, fn });
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    if (!this._listeners[event]) {
      this._listeners[event] = [];
    }
    this._listeners[event].push({ once: true, fn });
    return this;
  }

  off(event, fn) {
    if (!this._listeners[event]) {
      return this;
    }
    const listeners = this._listeners[event];
    const index = listeners.findIndex(l => l.fn === fn);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
    return this;
  }

  listenerCount(event) {
    if (!this._listeners[event]) {
      return 0;
    }
    return this._listeners[event].length;
  }

  emit(event, ...args) {
    if (!this._listeners[event]) {
      return false;
    }

    // Create a fixed snapshot of listeners at the start of emit
    const listeners = this._listeners[event].slice();
    const toRemove = [];

    let calledAny = false;

    for (const { once, fn } of listeners) {
      // If it's a once listener, mark it for removal before calling
      if (once) {
        toRemove.push(fn);
      }

      fn.call(this, ...args);
      calledAny = true;
    }

    // Remove once listeners that were marked
    for (const fn of toRemove) {
      const index = this._listeners[event].findIndex(l => l.fn === fn);
      if (index !== -1) {
        this._listeners[event].splice(index, 1);
      }
    }

    return calledAny;
  }
}

