  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const trimmed = part.trim();

    if (trimmed.length === 0) {
      throw new SyntaxError('empty part (malformed input)');
    }

    const dashIndex = trimmed.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      const num = parseInt(trimmed, 10);
      if (isNaN(num)) {
        throw new SyntaxError(`invalid number: "${trimmed}"`);
      }
      // parseInt handles leading zeros and non-numeric chars if we validate strictly:
      // We need to ensure the whole string is a valid integer (no decimals, no +, no letters)
      if (!/^-?\d+$/.test(trimmed)) {
        throw new SyntaxError(`invalid number: "${trimmed}"`);
      }
      result.add(num);
    } else {
      // Range: lo-hi
      const loStr = trimmed.slice(0, dashIndex);
      const hiStr = trimmed.slice(dashIndex + 1);

      if (loStr.length === 0 || hiStr.length === 0) {
        throw new SyntaxError(`invalid range: "${trimmed}"`);
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (isNaN(lo) || isNaN(hi)) {
        throw new SyntaxError(`invalid range: "${trimmed}"`);
      }

      // Check for extra characters (like decimals or letters) by re-matching
      if (!/^-?\d+$/.test(loStr) || !/^-?\d+$/.test(hiStr)) {
        throw new SyntaxError(`invalid range: "${trimmed}"`);
