                raise ValueError("Quoted field never closed")

            # Extract content between quotes, replacing "" with "
            content = line[i + 1:j]
            result = []
            k = 0
            while k < len(content):
                if k + 1 < len(content) and content[k:k+2] == '""':
                    result.append('"')
                    k += 2
                else:
                    result.append(content[k])
                    k += 1
            fields.append(''.join(result))

            # After closing quote, must be comma or end of line
            if j < n and line[j] != ',':
                raise ValueError("After quoted field must be comma or end of line")

            i = j
        else:
            # Unquoted field: read until comma or end
            j = i
            while j < n and line[j] != ',':
                j += 1
            fields.append(line[i:j])
            i = j

