  let value = n;
  let unitIndex = 0;

  while (unitIndex < units.length - 1 && value >= 1024) {
    value /= 1024;
    unitIndex++;
  }

  const roundedValue = Math.round(value * 10) / 10;
  const roundedInt = Math.round(roundedValue);

  if (roundedInt === 1024 && unitIndex < units.length - 1) {
    unitIndex++;
  }

  const finalValue = roundedInt === 1024 ? 1024 : roundedValue;
  const unit = units[unitIndex];

