function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const trimmedPart = part.trim();

    // Check for empty part (handles consecutive commas or leading/trailing commas)
    if (trimmedPart === '') {
      throw new SyntaxError('malformed part: empty part');
    }

    // Split into components (lo and hi)
    const components = trimmedPart.split('-');

    if (components.length > 2) {
      throw new SyntaxError(`malformed part: more than one dash ("${trimmedPart}")`);
    }

    // If only one component, it's a single number
    if (components.length === 1) {
      const num = Number(components[0]);
      if (Number.isNaN(num)) {
        throw new SyntaxError(`malformed part: cannot parse number ("${trimmedPart}")`);
      }
      result.add(num);
      continue;
    }

    // Two components: range
    const [loStr, hiStr] = components;

    // Check for empty lo or hi (e.g. "1-", "-3")
    if (loStr === '' || hiStr === '') {
      throw new SyntaxError(`malformed part: missing end ("${trimmedPart}")`);
    }

    // Parse lo and hi
    const lo = Number(loStr);
    const hi = Number(hiStr);

    if (Number.isNaN(lo) || Number.isNaN(hi)) {
      throw new SyntaxError(`malformed part: cannot parse numbers ("${trimmedPart}")`);
    }

    // Validate: non-negative integers only (no decimals, no plus signs, no negatives)
    // parseFloat ignores leading zeros and handles decimals, so we check strictness.
    // Check for decimal points or signs explicitly
    if (loStr !== String(lo) || hiStr !== String(hi)) {
      throw new SyntaxError(`malformed part: invalid integer format ("${trimmedPart}")`);
    }
    // Check for leading signs (+ or -)
    if (loStr.startsWith('+') || loStr.startsWith('-') || 
        hiStr.startsWith('+') || hiStr.startsWith('-')) {
      throw new SyntaxError(`malformed part: signed number ("${trimmedPart}")`);
    }

    if (lo > hi) {
      throw new RangeError(`start is greater than end ("${lo}-${hi}")`);
    }

    for (let n = lo; n <= hi; n++) {
      result.add(n);
    }
  }

