def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""

    # Check for any digit in input
    for ch in s:
        if '0' <= ch <= '9':
            raise ValueError("Input must not contain digits")

    if not s:
        return ""

    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            result.append(f"{count}{s[i-1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""

    result = []
    i = 0
    n = len(s)

    while i < n:
        # Extract digits for count
        start = i
        while i < n and '0' <= s[i] <= '9':
            i += 1

        if i == start:
            raise ValueError("Missing count")

        count_str = s[start:i]
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")

        if i >= n:
            raise ValueError("Missing character after count")

        char = s[i]
        result.append(char * count)
        i += 1

    return "".join(result)
