def spiral_order(matrix):
    if not matrix:
        return []

    rows = len(matrix)
    if rows == 0:
        return []

    cols = len(matrix[0])
    if cols == 0:
        return [x for row in matrix if row] or []

    # Check all rows have same length
    for row in matrix:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")

    # Check for empty matrix with non-empty rows list
    if cols == 0:
        return [row[0] for row in matrix] if rows > 0 and all(len(row) > 0 for row in matrix) else []

    result = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse from left to right along the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse from top to bottom along the right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        # Traverse from right to left along the bottom row (if there's a row left)
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        # Traverse from bottom to top along the left column (if there's a column left)
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result
