function flatten(arr, depth = 1) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`Expected an array, got ${typeof arr}`);
  }
  if (depth === Infinity) {
    // Infinite depth case: flatten recursively until no more arrays
    let result = [];
    const stack = [[arr, 0]]; // [currentArray, currentDepth]
    while (stack.length > 0) {
      const [currentArray, currentDepth] = stack.pop();
      for (let i = currentArray.length - 1; i >= 0; i--) {
        const item = currentArray[i];
        if (Array.isArray(item)) {
          stack.push([item, currentDepth + 1]);
        } else {
          result.push(item);
        }
      }
    }
    // Reverse because we traversed backwards
    return result.reverse();
  }

  if (depth < 0 || Number.isNaN(depth)) {
    throw new RangeError('depth must be a non-negative number or Infinity');
  }

  const result = [];

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    if (Array.isArray(item)) {
      if (depth > 0) {
        const flattened = flatten(item, depth - 1);
        for (let j = 0; j < flattened.length; j++) {
          result.push(flattened[j]);
        }
      } else {
        result.push(item);
      }
    } else {
      result.push(item);
    }
  }

  return result;
}

