function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const trimmed = part.trim();

    // Empty part (e.g., from trailing comma or ",,")
    if (trimmed === '') {
      throw new SyntaxError('empty part');
    }

    // Check for multiple dashes
    const dashIndex = trimmed.indexOf('-');
    if (dashIndex === -1) {
      // Single number
      const num = Number(trimmed);
      if (Number.isNaN(num) || trimmed.trim() === '') {
        throw new SyntaxError('malformed part');
      }
      // Allow leading zeros by parsing as number; NaN check above covers non-numeric
      // Also ensure it doesn't have a sign prefix that makes it non-integer-like
      if (!/^-?\d+$/.test(trimmed)) {
        throw new SyntaxError('malformed part');
      }
      result.add(num);
    } else if (dashIndex === 0 || dashIndex === trimmed.length - 1) {
      // Leading or trailing dash: " - " or "-1" or "1-" -> malformed
      throw new SyntaxError('malformed part');
    } else if (trimmed.indexOf('-', dashIndex + 1) !== -1) {
      // More than one dash
      throw new SyntaxError('malformed part');
    } else {
      // "lo-hi"
      const [loStr, hiStr] = trimmed.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part');
      }
      const lo = Number(loStr);
      const hi = Number(hiStr);
      if (Number.isNaN(lo) || Number.isNaN(hi)) {
        throw new SyntaxError('malformed part');
      }
      if (lo > hi) {
        throw new RangeError('start greater than end');
      }
      for (let n = lo; n <= hi; n++) {
        result.add(n);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

