    i = 0
    n = len(s)

    while i < n:
        # Extract the count (one or more digits)
        start = i
        while i < n and s[i].isdigit():
            i += 1

        # If no digits found (e.g., at end or after a non-digit), that's an error
        if start == i:
            raise ValueError("Missing count")

        count_str = s[start:i]
        # Check for leading zeros? Actually allowed, e.g., "01a" -> "a"
        # But count must be >= 1. "0a" is count 0, which is invalid.
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")

        # Now we need a non-digit character immediately after the digits
        if i >= n:
            raise ValueError("Missing character after count")

        char = s[i]
        # The character must not be a digit (implied by definition, but check anyway)
        # Actually, the spec says "char is any single non-digit character", so if it's a digit, it's an error.
        if char.isdigit():
            raise ValueError("Character must be non-digit")
        i += 1

        result.append(char * count)

    return "".join(result)
