function deepEqual(a, b) {
  if (a === b) {
    if (a === 0 && 1 / a !== 1 / b) {
      return false; // 0 and -0 check
    }
    if (a !== a && b !== b) {
      return true; // NaN === NaN
    }
    return true;
  }

  if (a === 0 && b !== 0) return false;
  if (a !== 0 && b === 0) return false;
  if (a !== a && b !== b) return true;

  const typeA = typeof a;
  const typeB = typeof b;

  if (typeA !== typeB) {
    return false;
  }

  if (typeA === 'object' || typeA === 'function') {
    if (a === null || b === null) return false;

    // Date handling
    if (a instanceof Date && b instanceof Date) {
      return a.getTime() === b.getTime();
    }

    // Array handling
    if (Array.isArray(a)) {
      if (!Array.isArray(b)) return false;
      if (a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        if (!deepEqual(a[i], b[i])) return false;
      }
      return true;
    }

    // Plain Object handling
    if (Object.prototype.toString.call(a) === '[object Object]' &&
        Object.prototype.toString.call(b) === '[object Object]') {
      const keysA = Object.keys(a);
      const keysB = Object.keys(b);

      if (keysA.length !== keysB.length) return false;

      for (const key of keysA) {
        if (!(key in b)) return false;
        if (!deepEqual(a[key], b[key])) return false;
      }
      return true;
    }

    // Functions: reference equality only (already handled by top-level ===)
    // But since === check at top handles reference equality for functions,
    // we fall through to false for different object types.
    return false;
  }

  return false;
}

