    // Check for empty parts (handles trailing comma, consecutive commas)
    if (part === '') {
      throw new SyntaxError('malformed part');
    }

    // Check for more than one dash
    const dashes = part.split('-');
    if (dashes.length > 2) {
      throw new SyntaxError('malformed part');
    }

    if (dashes.length === 2) {
      const [loStr, hiStr] = dashes;

      // Check for empty start or end after split
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part');
      }

      // Parse integers (handles leading zeros, but rejects floats, negatives with sign char if not parsed correctly, etc.)
      // We need to ensure no extra characters like '+', '-', or decimal points.
      // A regex that matches optional leading zeros and digits, but nothing else.
      if (!/^\d+$/.test(loStr)) {
        throw new SyntaxError('malformed part');
      }
      if (!/^\d+$/.test(hiStr)) {
        throw new SyntaxError('malformed part');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('start must not exceed end');
      }

      for (let n = lo; n <= hi; n++) {
        resultSet.add(n);
      }
    } else {
      // Single number
      const str = part.trim();
      if (!/^\d+$/.test(str)) {
        throw new SyntaxError('malformed part');
      }
      const num = parseInt(str, 10);
      resultSet.add(num);
    }
  }

  return Array.from(resultSet).sort((a, b) => a - b);
}

