def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    # Check for digits in input (must not contain any digit)
    for char in s:
        if char.isdigit():
            raise ValueError("Input must not contain digit characters")

    result = []
    prev_char = s[0]
    count = 1

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            result.append(f"{count}{prev_char}")
            prev_char = char
            count = 1

    # Append the last run
    result.append(f"{count}{prev_char}")

    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        # Parse the count (one or more digits)
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1

        if i == start:
            raise ValueError("Missing count at position {}".format(i))

        count_str = s[start:i]
        count = int(count_str)

        if count == 0:
            raise ValueError("Count must be at least 1")

        # Check if there's a character after the count
        if i >= len(s):
            raise ValueError("Missing character after count")

        char = s[i]
        i += 1

        result.append(char * count)

    return "".join(result)
