def spiral_order(matrix):
    if not matrix:
        return []

    # Check that all rows have the same length
    if not all(len(row) == len(matrix[0]) for row in matrix):
        raise ValueError("All rows must have the same length")

    if not all(row for row in matrix):
        # Check for empty rows (e.g., [[]] or [[], []])
        if not matrix[0]:
            return []

    rows = len(matrix)
    cols = len(matrix[0])

    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

    result = []

    while top <= bottom and left <= right:
        # Traverse right along the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse down along the right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        # Traverse left along the bottom row (if there are still rows left)
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        # Traverse up along the left column (if there are still columns left)
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result
