    if (trimmed === '') {
      throw new SyntaxError('malformed part');
    }

    // Check for multiple dashes
    const dashCount = (trimmed.match(/-/g) || []).length;
    if (dashCount === 0) {
      // Single number: must be non-negative integer (allow leading zeros)
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('malformed part');
      }
      const num = Number(trimmed);
      if (Number.isInteger(num) && num >= 0) {
        result.add(num);
      } else {
        throw new SyntaxError('malformed part');
      }
    } else if (dashCount === 1) {
      // Range: "lo-hi"
      const [loStr, hiStr] = trimmed.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part');
      }
      // Validate lo and hi are non-negative integers (allow leading zeros)
      if (!/^\d+$/.test(loStr) || !/.isNaN(Number(loStr))) {
        throw new SyntaxError('malformed part');
      }
      if (!/^\d+$/.test(hiStr)) {
        throw new SyntaxError('malformed part');
      }

      const lo = Number(loStr);
      const hi = Number(hiStr);

      // Check for non-negative integers (no decimals, no plus signs, no negatives)
      if (!Number.isInteger(lo) || !Number.isInteger(hi) || lo < 0 || hi < 0) {
        throw new SyntaxError('malformed part');
      }

      if (lo > hi) {
        throw new RangeError('start is greater than end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      // More than one dash
      throw new SyntaxError('malformed part');
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

