function formatTable(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }

  for (let i = 0; i < rows.length; i++) {
    if (!Array.isArray(rows[i])) {
      throw new TypeError('rows must be an array of arrays');
    }
  }

  if (rows.length === 0) {
    return '';
  }

  // Step 1: Normalize each cell: null/undefined -> "", others -> String(cell)
  const normalized = rows.map(row =>
    row.map(cell => (cell == null ? '' : String(cell)))
  );

  // Step 2: Determine max width per column
  const maxCols = normalized.reduce((max, row) => Math.max(max, row.length), 0);

  const colWidths = new Array(maxCols).fill(0);
  for (let i = 0; i < normalized.length; i++) {
    for (let j = 0; j < normalized[i].length; j++) {
      const len = normalized[i][j].length;
      if (len > colWidths[j]) {
        colWidths[j] = len;
      }
    }
  }

  // Step 3: Build output lines
  const lines = normalized.map(row => {
    const cells = [];
    for (let j = 0; j < maxCols; j++) {
      const cell = row[j] !== undefined ? row[j] : '';
      // If cell is shorter than column width, pad with spaces
      const padded = cell.padEnd(colWidths[j]);
      cells.push(padded);
    }
    // Join with " | ", then trim trailing spaces from the end of the line
    const line = cells.join(' | ');
    return line.trimEnd();
  });

