def is_balanced(code: str) -> bool:
    """
    Check if brackets are balanced, ignoring content inside double-quoted strings.
    - Brackets inside strings (including escaped quotes) do not count.
    - A string that isn't closed makes the result False.
    - Inside strings, a backslash escapes the next character.
    """
    stack = []
    i = 0
    n = len(code)
    in_string = False

    while i < n:
        char = code[i]

        if in_string:
            if char == '\\' and i + 1 < n:
                # Escape: skip the next character
                i += 2
                continue
            elif char == '"':
                in_string = False
            i += 1
            continue

        # Not in string
        if char == '"':
            in_string = True
            i += 1
            continue

        if char == '(':
            stack.append(')')
        elif char == '[':
            stack.append(']')
        elif char == '{':
            stack.append('}')
        elif char == ')':
            if not stack or stack[-1] != ')':
                return False
            stack.pop()
        elif char == ']':
            if not stack or stack[-1] != ']':
                return False
            stack.pop()
        elif char == '}':
            if not stack or stack[-1] != '}':
                return False
            stack.pop()

        i += 1

    # If we ended inside a string, that's unbalanced per spec
    if in_string:
        return False

    return len(stack) == 0
