function addDays(dateStr, days) {
  // Type checks
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (typeof days !== 'number' || !Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  // Validate format: YYYY-MM-DD (exactly 4-2-2 with dashes)
  if (typeof dateStr !== 'string' || dateStr.length !== 10) {
    throw new RangeError('dateStr must be exactly 10 characters in YYYY-MM-DD format');
  }

  const dateRegex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateStr.match(dateRegex);
  if (!match) {
    throw new RangeError('dateStr must be in YYYY-MM-DD format');
  }

  const [yearStr, monthStr, dayStr] = match.slice(1, 4);
  const year = parseInt(yearStr, 10);
  const month = parseInt(monthStr, 10);
  const day = parseInt(dayStr, 10);

  // Basic validation for month and day ranges before creating Date
  if (month < 1 || month > 12) {
    throw new RangeError('month must be between 01 and 12');
  }

  // Create a UTC date to avoid DST issues.
  // We use 'YYYY-MM-DD' string representation, then construct a Date object
  // by passing UTC components.
  const date = new Date(Date.UTC(year, month - 1, day));

  // Check if the date is valid (e.g., 2023-02-30 will become invalid after normalization)
  if (date.getFullYear() !== year ||
      date.getMonth() !== month - 1 ||
      date.getDate() !== day) {
    throw new RangeError('date is not a valid calendar date');
  }

  // Add days
  const dateToAdd = new Date(date.getTime());
  dateToAdd.setDate(dateToAdd.getDate() + days);

  const newYear = dateToAdd.getUTCFullYear();
  const newMonth = dateToAdd.getUTCMonth() + 1;
  const newDay = dateToAdd.getUTCDate();

  // Validate year range 0001..9999
  if (newYear < 1 || newYear > 9999) {
    throw new RangeError('resulting year must be between 0001 and 9999');
  }

  // Format output with zero-padding
  const formattedYear = String(newYear).padStart(4, '0');
  const formattedMonth = String(newMonth).padStart(2, '0');
  const formattedDay = String(newDay).padStart(2, '0');

  return `${formattedYear}-${formattedMonth}-${formattedDay}`;
}

