def search_rotated(nums, target):
    n = len(nums)
    if n == 0:
        return -1

    low, high = 0, n - 1
    while low <= high:
        mid = (low + high) // 2
        mid_val = nums[mid]

        if mid_val == target:
            return mid

        if mid_val < nums[high]:
            # Right part is sorted
            if mid_val < target <= nums[high]:
                low = mid + 1
            else:
                high = mid - 1
        elif mid_val > nums[high]:
            # Left part is sorted
            if nums[low] <= target < mid_val:
                high = mid - 1
            else:
                low = mid + 1
        else:
            # mid_val == nums[high] and low == high, only one element left
            return -1

    return -1
