    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        # Calculate length needed for this word to be added
        # If current_line is empty, no space needed before the word
        # Otherwise, need 1 space + word length
        if current_line:
            needed = current_length + 1 + len(word)
        else:
            needed = len(word)

        # If word is longer than width, it goes on its own line
        if len(word) > width:
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
                current_length = 0
            lines.append(word)
            continue

        # If the word fits, add it
        if needed <= width:
            current_line.append(word)
            current_length = needed
        else:
            # Word doesn't fit, start new line
            lines.append(" ".join(current_line))
            current_line = [word]
            current_length = len(word)

    # Don't forget the last line
    if current_line:
        lines.append(" ".join(current_line))

