        raise ValueError("missing AM/PM")

    # Time part must be in format H:MM or HH:MM
    if ':' not in time_part:
        raise ValueError("missing colon")

    parts = time_part.split(':')
    if len(parts) != 2:
        raise ValueError("invalid hour:minute format")

    hour_str = parts[0].strip()
    minute_str = parts[1]

    # Validate hour
    if not hour_str.isdigit():
        raise ValueError("hour must be digits")
    hour = int(hour_str)
    if hour == 0 or hour > 12:
        raise ValueError("hour must be 1-12")

    # Validate minute: must be exactly 2 digits, 00-59
    if len(minute_str) != 2 or not minute_str.isdigit():
