    attemptCount++;

    try {
      const result = fn(attemptCount);

      // If fn returns a promise, await it; otherwise await the result
      const resolved = await Promise.resolve(result);
      return resolved;
    } catch (err) {
      lastError = err;
      if (attemptCount >= attempts) {
        break;
      }
      // Continue to next attempt
    }
  }

  // All attempts failed
  return Promise.reject(lastError);
