function longestCommonPrefix(strs) {
  if (!Array.isArray(strs)) {
    throw new TypeError('Argument must be an array');
  }

  for (const s of strs) {
    if (typeof s !== 'string') {
      throw new TypeError('All elements must be strings');
    }
  }

  if (strs.length === 0) return '';
  if (strs.length === 1) return strs[0];

  const first = strs[0];

  // Helper to get code points (not code units) up to a given index (exclusive)
  const getPrefixCodePoints = (str, maxLen) => {
    const cpArray = [...str]; // splits by code points
    if (maxLen > cpArray.length) maxLen = cpArray.length;
    return cpArray.slice(0, maxLen);
  };

  // Find the minimum length (in code points) across all strings
  let minLen = first.length;
  for (let i = 1; i < strs.length; i++) {
    const cp = [...strs[i]];
    if (cp.length < minLen) minLen = cp.length;
  }

  // Compare code point by code point across all strings
  let resultCp = [];
  for (let i = 0; i < minLen; i++) {
    const c = getPrefixCodePoints(first, i + 1)[i];
    let match = true;
    for (let j = 1; j < strs.length; j++) {
      const otherCp = [...strs[j]];
      if (otherCp[i] !== c) {
        match = false;
        break;
      }
    }
    if (match) {
      resultCp.push(c);
    } else {
      break;
    }
  }

  return resultCp.join('');
}

