    for row in rows:
        for char in row:
            if char not in valid_chars:
                raise ValueError(f"Invalid character: {char!r}")

    # Count S and E
    start = None
    end = None
    count_s = 0
    count_e = 0

    for r_idx, row in enumerate(rows):
        for c_idx, char in enumerate(row):
            if char == 'S':
                start = (r_idx, c_idx)
                count_s += 1
            elif char == 'E':
                end = (r_idx, c_idx)
                count_e += 1

    if count_s != 1 or count_e != 1:
        raise ValueError("There must be exactly one S and one E")

    if start is None or end is None:
        raise ValueError("Start or exit not found")

    # BFS
    queue = deque([(start, 0)])
    visited = {start}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        (r, c), steps = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(rows) and 0 <= nc < len(rows[0]):
                cell = rows[nr][nc]
                if cell != '#' and (nr, nc) not in visited:
