    const otherCodePoints = [...strs[i].codePoints()];
    const minLen = Math.min(prefixCodePoints.length, otherCodePoints.length);

    let commonLen = 0;
    for (let j = 0; j < minLen; j++) {
      if (prefixCodePoints[j] !== otherCodePoints[j]) {
        break;
      }
      commonLen++;
    }

    prefixCodePoints.length = commonLen;
    if (commonLen === 0) {
      return '';
    }
  }

  return prefixCodePoints.length > 0 ? String.fromCodePoint(...prefixCodePoints) : '';
}

