    throw new TypeError('Argument must be an array');
  }

  for (const s of strs) {
    if (typeof s !== 'string') {
      throw new TypeError('All elements must be strings');
    }
  }

  if (strs.length === 0) {
    return '';
  }

  const first = strs[0];
  if (first === '') {
    return '';
  }

  // Convert to code points (code points are what we care about for prefix)
  // We will work with code points to ensure we never split a surrogate pair.
  const firstCodePoints = [...first];
  let len = firstCodePoints.length;

  for (let i = 1; i < strs.length; i++) {
    const s = strs[i];
    const sCodePoints = [...s];

    // Find the minimum length between current prefix length and current string length
    const limit = Math.min(len, sCodePoints.length);

    let j = 0;
    while (j < limit && firstCodePoints[j] === sCodePoints[j]) {
      j++;
    }
    len = j;

    if (len === 0) {
      return '';
    }
  }

  // Reconstruct the prefix from the first string using the determined length
  return firstCodePoints.slice(0, len).join('');
}

