function longestCommonPrefix(strs) {
  if (!Array.isArray(strs)) {
    throw new TypeError("Argument must be an array");
  }

  for (let i = 0; i < strs.length; i++) {
    if (typeof strs[i] !== "string") {
      throw new TypeError("All elements must be strings");
    }
  }

  if (strs.length === 0) {
    return "";
  }

  // Find the shortest string length to avoid out of bounds
  let minLen = strs.reduce((min, str) => {
    const len = str.length;
    return len < min ? len : min;
  }, strs[0].length);

  let prefix = "";
  let i = 0;

  while (i < minLen) {
    const charCode = strs[0].codePointAt(i);
    let same = true;
    for (let j = 1; j < strs.length; j++) {
      if (strs[j].codePointAt(i) !== charCode) {
        same = false;
        break;
      }
    }
    if (!same) break;
    // Extract the code point as a string (handles surrogates)
    const ch = String.fromCodePoint(charCode);
    prefix += ch;
    // Advance index by the length of the character (1 or 2)
    i += ch.length;
  }

  return prefix;
}

module.exports = { longestCommonPrefix };
