from collections import deque
from typing import List

def maze_steps(grid: List[str]) -> int:
    if not grid:
        raise ValueError("Grid must not be empty")

    rows = len(grid)
    cols = len(grid[0])

    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must have equal length")

    valid_chars = {'S', 'E', '#', '.'}
    for row in grid:
        for char in row:
            if char not in valid_chars:
                raise ValueError(f"Invalid character: {char}")

    start = None
    end = None
    count_s = 0
    count_e = 0

    for r in range(rows):
        for c in range(cols):
            char = grid[r][c]
            if char == 'S':
                start = (r, c)
                count_s += 1
            elif char == 'E':
                end = (r, c)
                count_e += 1

    if start is None or end is None:
        raise ValueError("Grid must contain exactly one 'S' and exactly one 'E'")
    if count_s != 1 or count_e != 1:
        raise ValueError("Grid must contain exactly one 'S' and exactly one 'E'")

    queue = deque([(start, 0)])
    visited = set((start,))

    while queue:
        (r, c), steps = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell != '#':
                        visited.add((nr, nc))
                        queue.append(((nr, nc), steps + 1))

    return -1
